"""docs/reference/api-reference.md is generated by scripts/gen_api_reference.py
(AST of api/*.py). Fails when the committed doc is stale, or when the
generator's idea of what main.py serves drifts from the real app."""
import importlib.util
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[3]
_spec = importlib.util.spec_from_file_location("gen_api_reference", ROOT / "scripts" / "gen_api_reference.py")
gen = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(gen)

IN_MAIN = {"/api/health", "/api/system/info", "/api/system/status", "/{full_path}"}
VERBS = ("GET", "POST", "PUT", "PATCH", "DELETE")


def test_api_reference_is_regenerated():
    assert gen.DOC.read_text(encoding="utf-8") == gen.render(), "run: python3 scripts/gen_api_reference.py"


def test_generator_sees_the_routes_the_app_serves():
    import main
    app = {(m.upper(), p) for p, ops in main.app.openapi()["paths"].items() if p not in IN_MAIN
           for m in ops if m.upper() in VERBS}
    ours = {(m, p.replace(":path}", "}")) for m, p in gen.served(schema_only=True) if m in VERBS}
    assert sorted(app - ours) == [] and sorted(ours - app) == []
